function page(seed: Seed): TreatmentPage {
  const canonicalPath = `/areas-de-intervencion/${sectorPath(seed.sector)}/${seed.slug}` as const;
  const related = [parentLinks[seed.sector], ...seed.relatedPaths.map((href) => relatedLinkFor(href)), methodLink, localLink, contactLink]
    .filter((item, index, all) => item.href && all.findIndex((candidate) => candidate.href === item.href) === index)
    .slice(0, 6);

  return {
    topicKey: `${seed.sector}:${seed.slug}`,
    canonicalPath,
    sector: seed.sector,
    slug: seed.slug,
    title: seed.title,
    description: seed.description,
    h1: seed.h1,
    summary: seed.summary,
    introFirstPerson: seed.opening,
    situations: {
      eyebrow: 'Situaciones frecuentes',
      title: 'Señales que conviene mirar sin etiquetar',
      body: [
        `Puede que ${seed.audience} llegue a consulta con ${list(seed.signs)}. No uso esa información para cerrar un diagnóstico rápido, sino para entender qué está pasando y desde cuándo preocupa.`,
        `También miro qué recursos ya existen alrededor: personas de apoyo, rutinas, escuela, trabajo, familia, cuerpo y momentos en los que el malestar afloja un poco.`
      ]
    },
    contextImpact: {
      eyebrow: 'Vida cotidiana',
      title: 'Por qué puede pesar en el día a día',
      body: [seed.impact, 'Cuando algo empieza a ocupar demasiado espacio, suele afectar a más de una zona. Por eso prefiero ordenar la demanda antes de decidir el camino: a veces el síntoma visible no es el centro del nudo.']
    },
    howICanHelp: {
      eyebrow: 'Cómo puedo acompañarte',
      title: 'Mi forma de trabajar este motivo',
      body: [seed.help, 'Trabajo con una mirada integradora: escucho la historia, el contexto, el cuerpo, los vínculos y las emociones. Si una herramienta concreta puede ayudar, la valoro dentro del proceso, no como una receta universal.']
    },
    process: {
      eyebrow: 'Proceso posible',
      title: 'Qué puede incluir el acompañamiento',
      body: [seed.process, 'El ritmo se revisa contigo. No hay plazos cerrados.'],
      links: [{ label: 'Leer cómo trabajo', href: '/como-trabajo' }, { label: 'Orientar mi consulta', href: '/contacto' }]
    },
    faq: seed.faqs,
    related,
    localCta: 'Si estás en Ciudad Real y quieres valorar si puedo acompañarte, puedes escribirme con una primera orientación breve. No necesitas contarlo todo en el primer mensaje.',
    sourceFacts: commonFacts,
    editorial: { status: 'preview-noindex-needs-human-approval', lastReviewed: today, similarityGroup: seed.group },
    boundaries: seed.boundaries ?? []
  };
}

