export const treatmentPages: readonly TreatmentPage[] = baseTreatmentPages.map((item, index, all) => ({
  ...item,
  related: withSectorNeighbors(item.related, item, index, all)
}));

function faq(topic: string, pairs: string[]): FaqItem[] {
  return [0, 2, 4, 6].map((index) => ({ question: pairs[index] ?? `¿Cómo sé si ${topic} necesita acompañamiento?`, answer: pairs[index + 1] ?? 'Podemos valorarlo con calma, mirando impacto, duración, recursos y contexto.' }));
}

function list(values: string[]): string {
  if (values.length <= 1) return values[0] ?? '';
  return `${values.slice(0, -1).join(', ')} o ${values[values.length - 1]}`;
}

export function sectorPath(sector: TreatmentSector): string {
  return ({
    'children-families': 'infancia-y-familias',
    adolescents: 'adolescentes',
    adults: 'adultos',
    perinatal: 'psicologia-perinatal',
    'education-training': 'orientacion-educativa-y-formacion'
  } satisfies Record<TreatmentSector, string>)[sector];
}

function relatedLinkFor(href: string): PageCard {
  if (href === '/psicologia-trauma-ciudad-real') return traumaPillarLink;
  const label = href.split('/').at(-1)?.replace(/-/g, ' ') ?? href;
  return { title: label[0]?.toUpperCase() + label.slice(1), body: 'Página relacionada para seguir orientando la consulta con contexto específico.', href };
}

function withSectorNeighbors(related: readonly PageCard[], page: TreatmentPage, _index: number, all: readonly TreatmentPage[]): PageCard[] {
  const sameSector = all.filter((item) => item.sector === page.sector);
  const sectorIndex = sameSector.findIndex((item) => item.canonicalPath === page.canonicalPath);
  const neighbors = [sameSector[(sectorIndex + sameSector.length - 1) % sameSector.length], sameSector[(sectorIndex + 1) % sameSector.length]]
    .filter((item): item is TreatmentPage => Boolean(item) && item.canonicalPath !== page.canonicalPath)
    .map((item) => ({ title: item.h1, body: item.summary, href: item.canonicalPath }));
  const merged = [related[0], ...neighbors, ...related.slice(1)].filter((item): item is PageCard => Boolean(item));
  return merged.filter((item, itemIndex, allItems) => item.href && allItems.findIndex((candidate) => candidate.href === item.href) === itemIndex).slice(0, 6);
}
